sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.wrm-faq { margin-top: 28px; }
.wrm-faq h2 {
  margin: 0 0 12px;
  font-size: 22px;
  color: var(--ink);
}

.wrm-faq-item {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-soft);
  margin-bottom: 8px;
  overflow: hidden;
}

.wrm-faq-q {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  background: transparent;
  border: 0;
  text-align: left;
  padding: 14px 16px;
  font-size: 14px;
  color: var(--ink);
  cursor: pointer;
}
.wrm-faq-q:hover { background: var(--surface-2); }
.wrm-faq-q:focus-visible { outline: 2px solid var(--clay); outline-offset: -2px; }
.wrm-faq-q.open { color: var(--clay); }

.wrm-faq-q .chev {
  font-size: 17px;
  color: var(--ink-3);
  flex: none;
  line-height: 1;
}
.wrm-faq-q.open .chev { color: var(--clay); }

.wrm-faq-a {
  padding: 0 16px 14px;
  font-size: 13px;
  color: var(--ink-2);
  border-top: 1px solid var(--line);
  padding-top: 12px;
}
.wrm-faq-a p { margin: 0 0 9px; }
.wrm-faq-a p:last-child { margin-bottom: 0; }
